func (this *Accessible) RemoveAccessibleValueListener(listener AccessibleValueListener) {
	this.CheckWidget()
	if listener == (nil) {
		Error(ERROR_NULL_ARGUMENT)
	}
	if this.accessibleValueListeners != (nil) {
		this.accessibleValueListeners.Remove(listener)
		if this.accessibleValueListeners.IsEmpty() {
			this.accessibleValueListeners = nil
		}
	}
}

func (this *Accessible) RemoveRelation(type_ int32, targetLike AccessibleLike) {
	var target *Accessible
	if targetLike != nil {
		target = targetLike.AsAccessible()
	}
	_ = target
	this.CheckWidget()
	if target == (nil) {
		Error(ERROR_NULL_ARGUMENT)
	}
	if this.relations[type_] != (nil) {
		this.relations[type_].RemoveTarget(target)
	}
}

func AccessibleRetainedAutoreleased(inObject *cocoa.NSArray) *cocoa.NSArray {
	var temp *cocoa.Id = upcastcocoaNSObjectTococoaId(inObject.Retain())
	var temp2 *cocoa.Id = upcastcocoaNSObjectTococoaId(cocoa.NewNSObjectOverload1(temp.Id).Autorelease())
	return cocoa.NewNSArrayOverload1(temp2.Id)
}

func (this *Accessible) RoleToOs(role int32) string {
	var nsReturnValue *cocoa.NSString = nil
	switch role {
	case ACCROLE_CLIENT_AREA:
		nsReturnValue = cocoa.OSNSAccessibilityGroupRole_
		break
	case ACCROLE_WINDOW:
		nsReturnValue = cocoa.OSNSAccessibilityWindowRole_
		break
	case ACCROLE_MENUBAR:
		nsReturnValue = cocoa.OSNSAccessibilityMenuBarRole_
		break
	case ACCROLE_MENU:
		nsReturnValue = cocoa.OSNSAccessibilityMenuRole_
		break
	case ACCROLE_MENUITEM:
		nsReturnValue = cocoa.OSNSAccessibilityMenuItemRole_
		break
	case ACCROLE_SEPARATOR:
		nsReturnValue = cocoa.OSNSAccessibilitySplitterRole_
		break
	case ACCROLE_TOOLTIP:
		nsReturnValue = cocoa.OSNSAccessibilityHelpTagRole_
		break
	case ACCROLE_SCROLLBAR:
		nsReturnValue = cocoa.OSNSAccessibilityScrollBarRole_
		break
	case ACCROLE_DIALOG:
		nsReturnValue = this.ConcatStringsAsRole(cocoa.OSNSAccessibilityWindowRole_, cocoa.OSNSAccessibilityDialogSubrole_)
		break
	case ACCROLE_LABEL:
		nsReturnValue = cocoa.OSNSAccessibilityStaticTextRole_
		break
	case ACCROLE_PUSHBUTTON:
		nsReturnValue = cocoa.OSNSAccessibilityButtonRole_
		break
	case ACCROLE_CHECKBUTTON:
		nsReturnValue = cocoa.OSNSAccessibilityCheckBoxRole_
		break
	case ACCROLE_RADIOBUTTON:
		nsReturnValue = cocoa.OSNSAccessibilityRadioButtonRole_
		break
	case ACCROLE_SPLITBUTTON:
		nsReturnValue = cocoa.OSNSAccessibilityMenuButtonRole_
		break
	case ACCROLE_COMBOBOX:
		nsReturnValue = cocoa.OSNSAccessibilityComboBoxRole_
		break
	case ACCROLE_TEXT:
		{
			var style int32 = this.control.impl.getStyle_()
			if (style & MULTI) != 0 {
				nsReturnValue = cocoa.OSNSAccessibilityTextAreaRole_
			} else {
				nsReturnValue = cocoa.OSNSAccessibilityTextFieldRole_
			}
			break
		}
	case ACCROLE_TOOLBAR:
		nsReturnValue = cocoa.OSNSAccessibilityToolbarRole_
		break
	case ACCROLE_LIST:
		nsReturnValue = cocoa.OSNSAccessibilityOutlineRole_
		break
	case ACCROLE_LISTITEM:
		nsReturnValue = cocoa.OSNSAccessibilityStaticTextRole_
		break
	case ACCROLE_COLUMN:
		nsReturnValue = cocoa.OSNSAccessibilityColumnRole_
		break
	case ACCROLE_ROW:
		nsReturnValue = this.ConcatStringsAsRole(cocoa.OSNSAccessibilityRowRole_, cocoa.OSNSAccessibilityTableRowSubrole_)
		break
	case ACCROLE_TABLE:
		nsReturnValue = cocoa.OSNSAccessibilityTableRole_
		break
	case ACCROLE_TABLECELL:
		nsReturnValue = cocoa.OSNSAccessibilityStaticTextRole_
		break
	case ACCROLE_TABLECOLUMNHEADER:
		nsReturnValue = cocoa.OSNSAccessibilityGroupRole_
		break
	case ACCROLE_TABLEROWHEADER:
		nsReturnValue = cocoa.OSNSAccessibilityGroupRole_
		break
	case ACCROLE_TREE:
		nsReturnValue = cocoa.OSNSAccessibilityOutlineRole_
		break
	case ACCROLE_TREEITEM:
		nsReturnValue = this.ConcatStringsAsRole(cocoa.OSNSAccessibilityOutlineRole_, cocoa.OSNSAccessibilityOutlineRowSubrole_)
		break
	case ACCROLE_TABFOLDER:
		nsReturnValue = cocoa.OSNSAccessibilityTabGroupRole_
		break
	case ACCROLE_TABITEM:
		nsReturnValue = cocoa.OSNSAccessibilityRadioButtonRole_
		break
	case ACCROLE_PROGRESSBAR:
		nsReturnValue = cocoa.OSNSAccessibilityProgressIndicatorRole_
		break
	case ACCROLE_SLIDER:
		nsReturnValue = cocoa.OSNSAccessibilitySliderRole_
		break
	case ACCROLE_LINK:
		nsReturnValue = cocoa.OSNSAccessibilityLinkRole_
		break
	case ACCROLE_CANVAS:
		nsReturnValue = cocoa.OSNSAccessibilityGroupRole_
		break
	case ACCROLE_GRAPHIC:
		nsReturnValue = cocoa.OSNSAccessibilityImageRole_
		break
	case ACCROLE_GROUP:
		nsReturnValue = cocoa.OSNSAccessibilityGroupRole_
		break
	case ACCROLE_CHECKMENUITEM:
		nsReturnValue = cocoa.OSNSAccessibilityMenuButtonRole_
		break
	case ACCROLE_RADIOMENUITEM:
		nsReturnValue = cocoa.OSNSAccessibilityMenuButtonRole_
		break
	case ACCROLE_FOOTER, ACCROLE_HEADER, ACCROLE_FORM, ACCROLE_PAGE, ACCROLE_SECTION:
		nsReturnValue = cocoa.OSNSAccessibilityGroupRole_
		break
	case ACCROLE_HEADING, ACCROLE_PARAGRAPH:
		nsReturnValue = cocoa.OSNSAccessibilityTextAreaRole_
		break
	case ACCROLE_CLOCK, ACCROLE_DATETIME, ACCROLE_CALENDAR, ACCROLE_ALERT, ACCROLE_ANIMATION, ACCROLE_DOCUMENT, ACCROLE_SPINBUTTON, ACCROLE_STATUSBAR:
		nsReturnValue = cocoa.OSNSAccessibilityUnknownRole_
	}
	return nsReturnValue.GetString()
}

func (this *Accessible) SelectionChanged() {
	this.CheckWidget()
	var eventSource *cocoa.Id = this.AccessibleHandle(this)
	if AccessibleDEBUG {
		fmt.Fprintln(os.Stdout, fmt.Sprintf("selectionChanged on %v", eventSource))
	}
	if this.currentRole == ACCROLE_TABLE {
		cocoa.OSNSAccessibilityPostNotification(eventSource.Id, cocoa.OSNSAccessibilitySelectedRowsChangedNotification_.Id)
	} else {
		cocoa.OSNSAccessibilityPostNotification(eventSource.Id, cocoa.OSNSAccessibilitySelectedChildrenChangedNotification_.Id)
	}
}
